# This code has been fully generated by an AI.
from pathlib import Path

import cv2
import numpy as np
import pytest

from hebocon.arena import UNITS, Arena, foreground, order_corners, whiten

from .conftest import CORNERS, draw_square, plate

IMAGES = Path(__file__).resolve().parent.parent / "test_images"


def blobs(mask: np.ndarray) -> int:
    return cv2.connectedComponents(mask.astype(np.uint8))[0] - 1


def test_order_corners_any_click_order():
    shuffled = [CORNERS[2], CORNERS[0], CORNERS[3], CORNERS[1]]
    assert np.allclose(order_corners(shuffled), np.array(CORNERS, np.float32))


def test_degenerate_corners_rejected():
    with pytest.raises(ValueError):
        Arena([(0, 0), (1, 1), (2, 2), (3, 3)])


def test_warp_is_rectangle_with_longer_side_units(arena):
    W, H = arena.size
    assert max(W, H) == pytest.approx(UNITS)
    view = arena.warp(plate(), 0.5)
    assert view.shape[:2] == (round(H * 0.5), round(W * 0.5))
    # Arenaecken landen auf den Bildecken.
    pts = cv2.perspectiveTransform(np.array([CORNERS], np.float32), arena.matrix(0.5))[0]
    assert np.allclose(pts, [[0, 0], [W / 2, 0], [W / 2, H / 2], [0, H / 2]], atol=0.5)


def test_padded_warp_shows_margin_around_same_field(arena):
    W, H = arena.size
    plain = arena.warp(plate(), 0.5)
    padded = arena.warp(plate(), 0.5, pad=40)
    assert padded.shape[:2] == (round((H + 80) * 0.5), round((W + 80) * 0.5))
    # Das Feld sitzt um genau den Rand verschoben im größeren Bild.
    inner = padded[20:20 + plain.shape[0], 20:20 + plain.shape[1]].astype(int)
    assert np.abs(inner - plain.astype(int)).mean() < 2


def test_outside_is_never_seen(arena):
    img = plate()
    # Dunkler Klotz außerhalb der Arena darf nach dem Entzerren nicht auftauchen.
    cv2.rectangle(img, (0, 0), (60, 60), (0, 0, 0), -1)
    assert blobs(foreground(arena.warp(img, 0.5))) == 0


def test_robot_is_solid_and_shadow_ignored(arena):
    img = plate()
    # Weicher Schatten: Boden auf 80 % abgedunkelt.
    shadow = img.copy()
    cv2.circle(shadow, (200, 300), 60, (144, 144, 144), -1)
    img = cv2.addWeighted(cv2.GaussianBlur(shadow, (31, 31), 0), 1.0, img, 0.0, 0)
    draw_square(img, (380, 200), 60)
    # Loch in der Mitte des Roboters, das gefüllt werden muss.
    cv2.rectangle(img, (375, 195), (385, 205), (180, 180, 180), -1)
    fg = foreground(arena.warp(img, 0.5))
    assert blobs(fg) == 1
    x, y = cv2.perspectiveTransform(np.array([[[380, 200]]], np.float32), arena.matrix(0.5))[0, 0]
    assert fg[int(y), int(x)]


def test_whiten_keeps_robot_and_whitens_floor(arena):
    img = plate()
    draw_square(img, (300, 250), 60)
    view = arena.warp(img, 0.5)
    out = whiten(view, foreground(view))
    x, y = cv2.perspectiveTransform(np.array([[[300, 250]]], np.float32), arena.matrix(0.5))[0, 0]
    assert (out[int(y), int(x)] == view[int(y), int(x)]).all()
    assert (out[2, 2] == 255).all()


def _real(name: str) -> np.ndarray:
    img = cv2.imread(str(IMAGES / name))
    if img is None:
        pytest.skip("Testbilder fehlen")
    h, w = img.shape[:2]
    arena = Arena([(0, 0), (w, 0), (w, h), (0, h)])
    return arena.warp(img, 640 / UNITS)


def test_real_empty_arena_has_no_robots():
    assert blobs(foreground(_real("Screenshot 2026-11-08 210040.png"))) == 0


def test_real_arena_finds_both_robots():
    assert blobs(foreground(_real("Screenshot 2026-11-08 210159.png"))) == 2
